insert into public.modulos (numero, slug, titulo, resumen, publicado) values (0, 'introduccion', 'Introducción y principios del curso', 'De qué trata el curso, cómo está organizado y los criterios que guían todos los módulos.', true);
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 1, 'de-que-trata-este-curso', '¿De qué trata este curso?' from public.modulos where numero = 0;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Un recorrido por el cielo desde <strong>dos miradas complementarias</strong> y, sobre todo, desde <strong>muchas culturas y épocas</strong>:</p>\n<ul><li><p><strong>Astronomía</strong>: la ciencia moderna de las estrellas, los planetas y el cosmos (la visión de la NASA y la física actual).</p></li><li><p><strong>Astrología</strong>: el lenguaje simbólico que relaciona los astros con la personalidad, el tiempo y los acontecimientos.</p></li></ul>\n<p>Y todo ello <strong>comparando cosmovisiones</strong>: cómo egipcios, babilonios, griegos, romanos, mayas, chinos y la tradición védica entendieron el cielo, incluyendo modelos geocéntricos y de tierra plana, junto a lo que sostiene hoy la astronomía moderna.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 0 and s.orden = 1;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 2, 'principios-del-curso', 'Principios del curso' from public.modulos where numero = 0;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Estos criterios guían <strong>todos</strong> los módulos:</p>\n<ul><li><p><strong>Libre albedrío</strong>: el curso no decide por ti qué cosmovisión es la verdadera. Expone cada una con su propia lógica, sus argumentos y sus fuentes, y eres tú quien saca sus conclusiones.</p></li><li><p><strong>Estructura de menos a más</strong>: cada módulo va de una introducción accesible, a un desarrollo de los conceptos clave, a una capa avanzada más profunda.</p></li><li><p><strong>La capa avanzada siempre documentada</strong>: toda afirmación de la parte avanzada se apoya en fuentes fidedignas y verificables (textos originales, obras académicas, datos astronómicos publicados).</p></li><li><p><strong>Verificable no significa \"verdadero por defecto\"</strong>: que una fuente sea verificable no la hace más cierta que otra. La visión moderna no tiene prioridad por ser la oficial.</p></li><li><p><strong>Cada afirmación atribuida a quien la sostiene</strong>: en lugar de \"esto es así\", diremos \"la cosmología moderna sostiene esto, según tal evidencia\" o \"la tradición egipcia sostenía esto otro, según tales textos\". Todas las visiones tienen el mismo rango; se especifica quién le da autoridad a cada una.</p></li><li><p><strong>Hecho frente a creencia</strong>: en los temas esotéricos y místicos se distingue con claridad entre un hecho histórico documentado y una creencia o interpretación simbólica.</p></li><li><p><strong>Módulo fundacional</strong>: \"Mirar el cielo\" es el más desarrollado, porque da la visión global y el vocabulario para entender todo lo demás. Los fenómenos observables se explican desde ambas cosmovisiones, la moderna y la terraplanista, lado a lado. Los demás módulos se profundizan sobre la marcha, según el interés.</p></li><li><p><strong>Hilo conductor histórico, sin fundir las visiones</strong>: un eje temporal muestra cómo se pasó de una cosmovisión a otra, pero cada una se presenta con su postura clara y su coherencia propia; ninguna se trata como la \"equivocada\" que otra vino a corregir.</p></li><li><p><strong>La arquitectura del cielo de cada tradición, aquí; su lado místico, en el módulo 8</strong>: en los módulos de observación, cada fenómeno se explica desde todas las cosmovisiones en pie de igualdad: la astronomía moderna, el modelo terraplanista, la cosmología bíblica y cabalística, el Libro de Enoc (con especial atención), la cristiana medieval, y las de sumerios, babilonios, egipcios, griegos y romanos. Solo se compara cómo entendía cada una la estructura física del cosmos. Los significados simbólicos y espirituales se reservan para el módulo 8.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 0 and s.orden = 2;
insert into public.modulos (numero, slug, titulo, resumen, publicado) values (1, 'mirar-el-cielo', 'Mirar el cielo', 'Qué vemos realmente a simple vista: estrellas, Sol, Luna, eclipses, planetas y zodiaco, explicados desde cada cosmovisión.', true);
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 1, 'introduccion-que-vemos-cuando-miramos-el-cielo', 'Introducción: qué vemos cuando miramos el cielo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Antes de cualquier teoría, está lo que cualquier persona ve con sus propios ojos. Si te quedas una noche entera mirando el cielo, notas algo asombroso: casi todas las estrellas se mueven, trazando arcos lentos de un lado al otro, mientras una sola parece quedarse quieta. En el hemisferio norte esa estrella es <strong>Polaris</strong>, la estrella polar, y las demás giran en círculos a su alrededor.</p>\n<p>Este es el <strong>módulo fundacional</strong> del curso, el más desarrollado, porque aquí aprendemos a observar y a nombrar lo que vemos: el movimiento de las estrellas, el camino del Sol, las fases de la Luna, los planetas que vagan entre las constelaciones. Es el vocabulario con el que entenderemos todo lo demás.</p>\n<p>Y lo haremos con una regla de oro: <strong>separar lo que se observa de cómo se explica</strong>. El movimiento de Polaris es un hecho que cualquiera puede comprobar. Por qué ocurre es ya una explicación, y de esas hay varias. A lo largo del módulo pondremos lado a lado las explicaciones de distintas cosmovisiones (la astronomía moderna, el modelo terraplanista, la cosmología bíblica y cabalística, la cristiana medieval y las de sumerios, egipcios, griegos y romanos), cada una con su propia lógica, para que veas cómo un mismo cielo admite lecturas distintas. Ninguna se presenta aquí como la verdadera: cada una se expone con sus propios argumentos, y la conclusión es tuya.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 1;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 2, 'como-esta-organizado-este-modulo', 'Cómo está organizado este módulo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Como todos los módulos del curso, este va <strong>de menos a más</strong>, en tres capas:</p>\n<ol><li><p><strong>Introducción accesible</strong> (la que acabas de leer): el cielo a simple vista, sin tecnicismos, para despertar la mirada.</p></li><li><p><strong>Desarrollo de los conceptos clave</strong>: aquí nombramos y entendemos los grandes fenómenos observables — el movimiento diario de las estrellas y Polaris, el recorrido anual del Sol y la eclíptica, las fases de la Luna, el vagar de los planetas, las constelaciones y cómo orientarse. Cada fenómeno se describe primero como observación, y luego se explica desde cada una de las cosmovisiones del curso.</p></li><li><p><strong>Capa avanzada documentada</strong>: la parte más profunda, donde entramos en los detalles (ángulos, mediciones, cómo se predicen los fenómenos) y donde <strong>toda afirmación va con su fuente verificable</strong>, atribuida a quien la sostiene. Ninguna visión se da por verdadera por defecto.</p></li></ol>\n<p>Así puedes quedarte en la capa que quieras según tu interés, o recorrerlas todas en orden.</p>\n<p>Junto al texto encontrarás imágenes y animaciones. Cada una lleva una etiqueta que dice qué es:</p>\n<ul><li><p><strong>Fotografía real</strong>: tomada con una cámara, con su autor, su licencia y su fuente.</p></li><li><p><strong>Obra histórica</strong>: un grabado, un mapa o un manuscrito de época, con su fecha.</p></li><li><p><strong>Esquema</strong>, <strong>animación</strong> o <strong>interactivo</strong>: un dibujo hecho para este curso, simplificado a propósito, que indica qué modelo representa.</p></li><li><p><strong>Imagen generada por IA</strong>: por ahora no hay ninguna; si alguna vez se usa, se dirá expresamente.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 2;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 3, 'el-movimiento-de-las-estrellas-y-el-misterio-de-polaris', 'El movimiento de las estrellas y el misterio de Polaris' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<p>Si apuntas una cámara al cielo nocturno del hemisferio norte y dejas el obturador abierto varias horas, las estrellas no salen como puntos, sino como <strong>arcos de círculo</strong>. Y todos esos arcos comparten un mismo centro: un punto casi inmóvil junto al cual hay una estrella brillante, Polaris. Cuanto más cerca de ella, más pequeño el arco; las estrellas muy próximas apenas se mueven, y Polaris casi nada. Esto es un <strong>hecho observable</strong>, comprobable por cualquiera, en cualquier época, y así lo registraron todas las culturas.</p>\n<p>Un segundo hecho: según cuán al norte o al sur te encuentres, Polaris aparece más alta o más baja en el cielo. En el ecuador queda justo en el horizonte; según subes hacia el norte, sube contigo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'animacion', '{"componente": "arcos-polaris", "etiqueta": "Animación", "modelo": "Observación", "pie": "Una noche mirando al polo celeste, en el hemisferio norte y en el sur: las estrellas dejan arcos en torno a cada polo. Cambia de hemisferio con los botones."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'imagen', '{"tipo": "foto", "url": "https://noirlab.edu/public/media/archives/images/screen/iotw2033a.jpg", "enlace": "https://kpno.noirlab.edu/images/iotw2033a/", "pie": "Hemisferio norte: fotografía de larga exposición en el observatorio de Kitt Peak (Arizona). Las estrellas trazan arcos en torno a Polaris.", "credito": "KPNO/NOIRLab/NSF/AURA", "licencia": "CC BY 4.0", "grande": "https://noirlab.edu/public/media/archives/images/large/iotw2033a.jpg"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/171109-cc.jpg", "enlace": "https://www.eso.org/public/images/171109-cc/", "pie": "Hemisferio sur: fotografía de larga exposición con objetivo de ojo de pez en el observatorio Paranal (Chile). Los arcos giran en torno a otro punto del cielo, sin estrella brillante en el centro.", "credito": "ESO/A. Santerne", "licencia": "CC BY 4.0", "grande": "https://cdn.eso.org/images/large/171109-cc.jpg"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que Polaris parece quieta porque está <strong>casi alineada con el eje de rotación de la Tierra</strong>. Según este modelo, la Tierra gira sobre ese eje una vez al día, y como Polaris queda prácticamente en su prolongación, se mantiene fija mientras el resto del cielo parece girar a su alrededor. Para este modelo, que la altura de Polaris cambie con la latitud es consecuencia de que la Tierra sea esférica: el ángulo de Polaris sobre el horizonte equivale a la latitud del observador.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'imagen', '{"tipo": "foto", "url": "https://images-assets.nasa.gov/image/as17-148-22727/as17-148-22727~medium.jpg", "enlace": "https://images.nasa.gov/details/as17-148-22727", "pie": "La NASA la publica como una fotografía tomada por la tripulación del Apolo 17 en 1972, de camino a la Luna. El modelo moderno la presenta entre sus pruebas; los defensores de la Tierra plana cuestionan la autenticidad de este tipo de imágenes.", "credito": "NASA", "licencia": "Dominio público", "grande": "https://images-assets.nasa.gov/image/as17-148-22727/as17-148-22727~orig.jpg", "fecha": "1972"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista sostiene que Polaris es una estrella <strong>fija situada justo encima del Polo Norte</strong>, centro de un plano terrestre, y que las estrellas giran en círculo sobre ese plano como una cúpula que rota. En esta visión, los arcos circulares se explican por ese giro de la bóveda, no por el movimiento de la Tierra. Que Polaris baje en el cielo al viajar hacia el sur lo atribuyen a la <strong>perspectiva</strong>: igual que una farola parece más baja cuanto más te alejas de ella, la estrella se acercaría al horizonte a medida que el observador se aleja del centro.</p>\n<p><strong>El cielo del sur, un punto debatido.</strong> En el hemisferio sur las estrellas giran en sentido contrario alrededor de otro punto del cielo. La propia wiki de la Flat Earth Society reconoce que es un asunto muy discutido entre sus defensores, y recoge tres propuestas:</p>\n<ul><li><p><strong>Un solo centro, por perspectiva.</strong> Todo el cielo gira en torno al norte, pero quien mira hacia el sur ve las estrellas avanzar en sentido contrario, igual que algo que gira sobre nuestra cabeza parece girar al revés según hacia dónde miremos. En la wiki se atribuye a un colaborador que firma como P-Brane.</p></li><li><p><strong>Un solo centro, por efecto de cúpula.</strong> Dentro de la hipótesis de la «aceleración electromagnética», según la cual la luz se curva hacia arriba al recorrer grandes distancias, el cielo se vería como a través de una cúpula de cristal, y eso invertiría el giro aparente en el sur.</p></li><li><p><strong>Dos centros de giro.</strong> El modelo bipolar propone un segundo polo en el sur con su propio cielo giratorio encima. Exige un mapa distinto del de Gleason, con dos centros en lugar de uno.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 8, 'interactivo', '{"componente": "sur-plano", "etiqueta": "Interactivo", "modelo": "Según el modelo plano: tres propuestas", "pie": "Las tres propuestas que recoge la wiki de la Flat Earth Society para el giro del cielo del sur. Esquemas simplificados."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 9, 'imagen', '{"tipo": "obra", "url": "https://iiif.digitalcommonwealth.org/iiif/2/commonwealth:7h149v867/full/1400,/0/default.jpg", "enlace": "https://collections.leventhalmap.org/search/commonwealth:7h149v85z", "pie": "Mapa del mundo de Alexander Gleason (1892), con el polo norte en el centro y el borde del sur alrededor. Es la disposición que suele usarse para representar el modelo plano de un solo centro. Amplíalo para leer sus anotaciones.", "credito": "Alexander Gleason, 1892. Leventhal Map & Education Center (Biblioteca Pública de Boston)", "licencia": "Sin restricciones de uso conocidas", "grande": "https://iiif.digitalcommonwealth.org/iiif/2/commonwealth:7h149v867/full/3000,/0/default.jpg", "iiif": "https://iiif.digitalcommonwealth.org/iiif/2/commonwealth:7h149v867", "tam": [4773, 6794], "fecha": "1892"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 10, 'texto', '{"html": "<h3>Un dato que cambia todo: la estrella polar no siempre fue Polaris</h3>\n<p>Un hecho observable a muy largo plazo, registrado desde la Antigüedad: el punto en torno al que giran las estrellas <strong>se desplaza lentamente</strong>. Hiparco lo notó comparando sus mediciones con otras más antiguas, y la astronomía moderna calcula que ese punto completa un gran círculo en unos 26.000 años. A esto se le llama <strong>precesión</strong>. Según ese cálculo, hacia el 2700 a. C. la estrella más cercana a ese punto era <strong>Thuban</strong>, en la constelación del Dragón; en tiempos de los griegos clásicos no había ninguna estrella brillante justo en el polo; Polaris alcanzará su máxima cercanía hacia el año 2100, y dentro de unos 12.000 años el papel lo tendrá <strong>Vega</strong>. Esto importa porque cada cultura vio un cielo polar distinto, y cualquier explicación del cielo, sea cual sea su modelo, tiene que dar cuenta también de este lento desplazamiento.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 11, 'interactivo', '{"componente": "precesion", "etiqueta": "Interactivo", "modelo": "Observación, con el cálculo moderno de la precesión", "pie": "Mueve el año y observa cómo el polo celeste pasa de Thuban a Polaris y a Vega."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 12, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Concebían el universo como <strong>An</strong> (el cielo) sobre <strong>Ki</strong> (la tierra). En las tablillas astronómicas babilónicas conocidas como MUL.APIN (compiladas hacia el 1000 a. C.), el cielo se divide en tres franjas o \"caminos\": el de Anu en el centro, el de Enlil al norte y el de Ea al sur. Las estrellas que giran cerca del polo pertenecían al camino de Enlil.</p>\n<p><strong>Egipcios.</strong> Imaginaban el cielo como el cuerpo de la diosa <strong>Nut</strong>, arqueado sobre la tierra. Llamaban a las estrellas circumpolares, las que nunca se ponen, <em>ikhemu-sek</em>, \"las que no conocen la destrucción\" o \"imperecederas\", y aparecen en los Textos de las Pirámides. En su época la estrella polar era Thuban; algunos investigadores han propuesto que un conducto de la Gran Pirámide apuntaba hacia la región polar, aunque es una interpretación debatida.</p>\n<p><strong>Griegos.</strong> Concibieron una <strong>esfera celeste</strong> que gira en torno a un eje fijo, con la Tierra en el centro. Aristóteles, en <em>Sobre el cielo</em>, usó precisamente este fenómeno como argumento: al viajar al norte o al sur cambian las estrellas visibles, lo que para él indicaba una Tierra esférica y no muy grande. Hiparco, hacia el 130 a. C., fue quien detectó la precesión comparando sus mediciones con otras más antiguas.</p>\n<p><strong>Romanos y el mundo grecorromano.</strong> Heredaron y sistematizaron el modelo griego. Ptolomeo, en el <em>Almagesto</em> (siglo II d. C., en Alejandría), fijó el modelo geocéntrico de esferas que dominaría unos catorce siglos. Autores latinos como Cicerón (<em>El sueño de Escipión</em>) describieron el cosmos como nueve esferas encajadas, con la de las estrellas fijas girando por fuera.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El Génesis describe un <strong>firmamento</strong> (<em>raqia</em>) que separa las aguas de arriba de las de abajo, y en el que se colocan el Sol, la Luna y las estrellas. La tradición rabínica hablaba de varios cielos superpuestos, a menudo siete. El Talmud (Pesajim 94b) recoge un debate notable: los sabios de Israel sostenían que de noche el Sol pasaba por encima del firmamento, y los sabios de otras naciones que pasaba por debajo de la tierra; el propio Rabí Yehudá HaNasí concedió que la segunda postura parecía más acertada.</p>\n<p><strong>Libro de Enoc.</strong> El llamado <em>1 Enoc</em> es una colección de textos judíos antiguos; se conserva completo en ge''ez (etiópico), es canónico en la Iglesia ortodoxa etíope Tewahedo, y en Qumrán se hallaron fragmentos en arameo. La Epístola de Judas (versículos 14-15) cita un pasaje suyo. Su parte astronómica, el <em>Libro de las Luminarias</em> (capítulos 72-82), está considerada por los especialistas entre las secciones más antiguas, quizá del siglo III a. C. En él, el ángel Uriel muestra a Enoc las leyes de los astros. En el <em>Libro de los Vigilantes</em> (capítulos 33-36) Enoc viaja a los confines de la tierra y ve las <strong>puertas del cielo</strong> por donde salen las estrellas, y en el norte otras puertas de las que salen los vientos. Es decir, un cielo con límites, aberturas y salidas fijas, donde cada astro tiene su puerta y su orden.</p>\n<p><strong>Cábala.</strong> Su texto central, el <em>Zóhar</em> (difundido en Castilla a finales del siglo XIII), contiene un pasaje atribuido a Rav Hamnuná Saba según el cual la tierra gira como una esfera, de modo que cuando es de día para unos es de noche para otros. Es un ejemplo de cómo dentro de una misma tradición conviven modelos distintos del cielo.</p>\n<p><strong>Cristianismo medieval.</strong> La visión dominante, la de Tomás de Aquino o la que retrata Dante, adoptó el cosmos de Aristóteles y Ptolomeo: la Tierra esférica en el centro, rodeada por las esferas de la Luna, Mercurio, Venus, el Sol, Marte, Júpiter, Saturno y las estrellas fijas, luego el <em>primer móvil</em>, que imprime el giro diario a todo, y por fin el <strong>Empíreo</strong>. El manual universitario de astronomía más usado, <em>De sphaera</em> de Sacrobosco (siglo XIII), enseñaba la Tierra esférica. Hubo voces minoritarias distintas, como Cosmas Indicopleustes (siglo VI), que describió un mundo con forma de tabernáculo bajo una bóveda.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 13, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Scenographia_Systematis_mundani_Ptolemaici.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Cellarius_Harmonia_Macrocosmica_-_Scenographia_Systematis_mundani_Ptolemaici.jpg", "pie": "El sistema de Ptolomeo en el atlas «Harmonia Macrocosmica» de Andreas Cellarius (1660): la Tierra en el centro, rodeada por las esferas de los astros.", "credito": "Andreas Cellarius", "licencia": "Dominio público", "grande": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Scenographia_Systematis_mundani_Ptolemaici.jpg?width=3200", "fecha": "1660"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 14, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Flammarion.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Flammarion.jpg", "pie": "Grabado publicado por Camille Flammarion en «L''atmosphère» (París, 1888): un viajero asoma la cabeza más allá de la bóveda del cielo. Aunque a menudo se presenta como medieval, es del siglo XIX.", "credito": "Autor desconocido, en C. Flammarion, 1888", "licencia": "Dominio público", "grande": "https://commons.wikimedia.org/wiki/Special:FilePath/Flammarion.jpg?width=3200", "fecha": "1888"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 15, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/WorldMapCosmasIndicopleustes.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:WorldMapCosmasIndicopleustes.jpg", "pie": "Mapa del mundo de la «Topografía cristiana» de Cosmas Indicopleustes (siglo VI), tal como se conserva en copias manuscritas: la tierra habitada rodeada por el océano.", "credito": "Cosmas Indicopleustes (copia manuscrita)", "licencia": "Dominio público", "grande": "https://commons.wikimedia.org/wiki/Special:FilePath/WorldMapCosmasIndicopleustes.jpg?width=3200", "fecha": "Siglo VI"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 16, 'texto', '{"html": "<h3>Lo que cada modelo le pregunta al otro</h3>\n<p>Las dos explicaciones parten del mismo hecho — los arcos en torno a Polaris — y cada una lo explica con su propia lógica. Entre sus defensores hay preguntas cruzadas que cada parte considera decisivas. Aquí se recogen tal como las plantea cada una, junto con la respuesta que da la otra, para que puedas valorarlas tú.</p>\n<p><strong>Lo que los defensores de la Tierra plana preguntan al modelo moderno.</strong></p>\n<ul><li><p><em>¿Por qué no sentimos que la Tierra gira?</em> Según el modelo moderno, en el ecuador la superficie se movería a unos 1.670 km/h. Su respuesta es que un movimiento constante no se percibe, igual que no se nota la velocidad dentro de un avión en vuelo estable; solo se notan los cambios de velocidad.</p></li><li><p><em>¿Por qué el horizonte se ve plano y siempre a la altura de los ojos?</em> El modelo moderno responde que, con el tamaño que atribuye a la Tierra, la curvatura es muy suave a escala humana, y que el descenso del horizonte existe pero es pequeño y se mide con instrumentos desde lugares altos.</p></li><li><p><em>¿Por qué a veces se ven costas o edificios muy lejanos que la curvatura debería ocultar?</em> El modelo moderno lo atribuye a la refracción atmosférica, que curva la luz cerca del suelo y cambia con la temperatura del aire.</p></li></ul>\n<p><strong>Lo que los defensores del modelo moderno preguntan al modelo plano.</strong></p>\n<ul><li><p><em>¿Qué pasa en el hemisferio sur?</em> Allí Polaris no se ve, y las estrellas giran en torno a otro punto, en sentido contrario. Dentro del modelo plano hay tres propuestas, explicadas más arriba en su apartado, y sus defensores no coinciden en una sola.</p></li><li><p><em>¿Por qué los barcos que se alejan desaparecen empezando por el casco?</em> Muchos defensores del modelo plano lo atribuyen a la perspectiva y a la refracción, y afirman que con un buen zoom el barco vuelve a verse entero.</p></li><li><p><em>¿Cómo se explican los eclipses de Luna?</em> Se trata en su propio apartado, más abajo.</p></li></ul>\n<p>La capa avanzada del módulo recogerá las fuentes de cada postura y los experimentos que cada parte propone.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 4, 'el-sol-las-estaciones-y-la-ecliptica', 'El Sol, las estaciones y la eclíptica' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>El Sol no sale siempre por el mismo punto: a lo largo del año su salida se desplaza por el horizonte, hacia el norte hasta el <strong>solsticio de verano</strong> y hacia el sur hasta el <strong>solsticio de invierno</strong>. En los <strong>equinoccios</strong> sale casi exactamente por el este.</p></li><li><p>Su altura a mediodía y la duración del día cambian con las estaciones.</p></li><li><p>Las constelaciones visibles de noche cambian a lo largo del año. Todas las tradiciones dedujeron de ello que el Sol recorre lentamente un camino entre las estrellas, siempre el mismo: la <strong>eclíptica</strong>.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que la Tierra da una vuelta al Sol cada año con su eje inclinado unos 23,4°. Esa inclinación hace que cada hemisferio reciba la luz más directa en una mitad del año: de ahí las estaciones. La eclíptica es la proyección en el cielo del plano de la órbita terrestre.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista sostiene que el Sol es mucho más pequeño y cercano, y gira en círculo por encima del plano terrestre. A lo largo del año ese círculo se estrecha y se ensancha: en junio recorre una órbita interior (sobre el trópico de Cáncer) y en diciembre una exterior (sobre el de Capricornio). Su luz funcionaría como un foco que ilumina solo una zona, lo que explicaría el día, la noche y las estaciones.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'interactivo', '{"componente": "sol-dos-modelos", "etiqueta": "Interactivo", "modelo": "Dos modelos: moderno y plano", "pie": "El mismo año explicado por los dos modelos. Arriba, la Tierra inclinada alrededor del Sol; abajo, el Sol girando sobre el plano entre los trópicos. Esquemas, no a escala."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> El Sol era el dios Utu (Shamash en acadio). En los sellos cilíndricos aparece saliendo entre dos montañas por una puerta del este. Las tablillas MUL.APIN ya registran los solsticios y equinoccios y la duración cambiante de los días.</p>\n<p><strong>Egipcios.</strong> El Sol, Ra, recorría de día el cuerpo de Nut en una barca; al atardecer Nut lo engullía y de noche atravesaba la <strong>Duat</strong>, el mundo inferior, para renacer al amanecer. Así lo muestra el texto llamado <em>Libro de Nut</em> (o <em>Fundamentos del curso de las estrellas</em>).</p>\n<p><strong>Griegos.</strong> El Sol iba en su propia esfera, inclinada respecto al ecuador celeste: los griegos midieron esa inclinación de la eclíptica. Eratóstenes, hacia el 240 a. C., comparó la sombra del Sol en Siena y en Alejandría el mismo día y, suponiendo una Tierra esférica y un Sol lejano, calculó la circunferencia terrestre.</p>\n<p><strong>Romanos y Ptolomeo.</strong> En el <em>Almagesto</em>, el Sol ocupa la cuarta esfera contando desde la Tierra, y su movimiento algo desigual a lo largo del año se explica con un círculo desplazado del centro.</p>\n<p><strong>Cosmología bíblica.</strong> El Salmo 19 describe al Sol saliendo como un esposo de su tálamo y recorriendo el cielo de un extremo a otro. El Eclesiastés (1:5) dice que el Sol sale, se pone y vuelve presuroso a su lugar para salir de nuevo. En Josué 10 el Sol se detiene sobre Gabaón.</p>\n<p><strong>Libro de Enoc.</strong> Es el texto antiguo que describe el recorrido solar con más detalle (capítulo 72). El cielo tiene <strong>seis puertas al este y seis al oeste</strong>. El Sol sale por una puerta distinta según la época del año y avanza de puerta en puerta, mes a mes. El día y la noche se miden en dieciocho partes que se reparten de forma distinta según la puerta: en el día más largo, doce partes de día y seis de noche. De noche, dice el texto, el Sol regresa <strong>por el norte</strong> para volver a salir por el este. El año resultante es de <strong>364 días</strong>, exactamente 52 semanas, y el libro defiende ese calendario frente a otros.</p>\n<p><strong>Cristianismo medieval.</strong> Siguió el modelo de Ptolomeo: el Sol en la cuarta esfera, movido por la esfera superior. El <em>De sphaera</em> de Sacrobosco explicaba las estaciones por la inclinación de la eclíptica sobre una Tierra esférica e inmóvil.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Solis_circa_Orbem_Terrarum_Spiralis_Revolutio.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Cellarius_Harmonia_Macrocosmica_-_Solis_circa_Orbem_Terrarum_Spiralis_Revolutio.jpg", "pie": "Cellarius (1660): el recorrido en espiral del Sol alrededor de la Tierra a lo largo del año, según el modelo geocéntrico.", "credito": "Andreas Cellarius", "licencia": "Dominio público", "grande": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Solis_circa_Orbem_Terrarum_Spiralis_Revolutio.jpg?width=3200", "fecha": "1660"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'interactivo', '{"componente": "puertas-enoc", "etiqueta": "Interactivo", "modelo": "Según el Libro de Enoc", "pie": "Libro de Enoc, cap. 72: el Sol sale cada mes por una de las seis puertas del este."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 5, 'la-luna-y-sus-fases', 'La Luna y sus fases' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>La Luna pasa de creciente a llena y de menguante a nueva en unos <strong>29,5 días</strong>.</p></li><li><p>Siempre muestra la misma cara.</p></li><li><p>La parte iluminada siempre mira hacia donde está el Sol.</p></li><li><p>Cada día sale, de media, unos 50 minutos más tarde que el anterior.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'interactivo', '{"componente": "fases-luna", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Arrastra para recorrer un mes lunar de unos 29,5 días. El botón muestra, además, el esquema con el que lo explica el modelo moderno."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/eso1210a.jpg", "enlace": "https://www.eso.org/public/images/eso1210a/", "pie": "Luna creciente sobre el observatorio Paranal (Chile), el 27 de octubre de 2011. La parte oscura brilla débilmente: es la llamada luz cenicienta.", "credito": "ESO/B. Tafreshi (twanight.org)", "licencia": "CC BY 4.0", "grande": "https://cdn.eso.org/images/large/eso1210a.jpg", "fecha": "2011"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que la Luna no tiene luz propia: refleja la del Sol mientras gira alrededor de la Tierra. Según el ángulo entre Sol, Tierra y Luna vemos más o menos de su mitad iluminada, y eso son las fases. Muestra siempre la misma cara porque tarda lo mismo en girar sobre sí misma que en dar la vuelta a la Tierra.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>En el modelo terraplanista la Luna, como el Sol, es un astro pequeño y cercano que gira sobre el plano. Sobre su luz y sus fases hay dos posturas:</p>\n<ul><li><p><strong>Luz propia.</strong> Samuel Rowbotham, en <em>Zetetic Astronomy: Earth Not a Globe</em> (1881), sostuvo que la Luna brilla con luz propia y es semitransparente. Argumentaba que su luz tiene un carácter distinto del de la luz solar y que una esfera que solo reflejara la luz del Sol no podría verse iluminada por igual en toda su cara.</p></li><li><p><strong>Luz del Sol con rayos curvos.</strong> La wiki de la Flat Earth Society propone que la Luna sí recibe la luz del Sol, pero que esos rayos se curvan hacia arriba (la «aceleración electromagnética»). Las fases dependerían de la posición y la altura de la Luna respecto al Sol: llena cuando está lejos del Sol y más alta, nueva cuando está cerca y más baja. La propia wiki admite que no se conoce el mecanismo que curvaría la luz.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> La Luna era el dios Nanna (Sin en acadio). Su calendario era lunar: el mes empezaba con la primera observación de la Luna creciente tras la puesta del Sol. Las tablillas MUL.APIN enumeran las constelaciones \"en el camino de la Luna\".</p>\n<p><strong>Egipcios.</strong> La Luna se asociaba a los dioses Thot y Jonsu. Junto a su calendario civil de 365 días, usaban un calendario lunar para las fiestas religiosas.</p>\n<p><strong>Griegos.</strong> Anaxágoras (siglo V a. C.) sostuvo que la Luna recibe su luz del Sol. Aristarco de Samos (siglo III a. C.) usó la media luna para intentar calcular las distancias relativas de la Luna y el Sol.</p>\n<p><strong>Romanos y Ptolomeo.</strong> La Luna ocupa la esfera más cercana a la Tierra. Esa esfera marcaba una frontera: por debajo, el mundo cambiante; por encima, el cielo incorruptible.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El Génesis (1:16) habla de dos grandes lumbreras, la mayor para el día y la menor para la noche, y el Salmo 104 dice que la Luna se hizo para marcar los tiempos. El calendario hebreo es lunisolar: meses lunares ajustados al año solar añadiendo un mes extra en algunos años.</p>\n<p><strong>Libro de Enoc.</strong> Los capítulos 73-74 tratan de la Luna. Su círculo es como el del Sol, entra y sale por las mismas puertas, y su luz crece en una séptima parte cada vez y luego mengua del mismo modo. El texto compara el año lunar de <strong>354 días</strong> con su año solar de 364 y explica la diferencia que se acumula entre ambos.</p>\n<p><strong>Cristianismo medieval.</strong> Mantuvo el modelo aristotélico: la esfera de la Luna separaba el mundo terrenal, sujeto a cambio y corrupción, del mundo celeste, perfecto e inmutable.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 6, 'los-eclipses', 'Los eclipses' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>Los <strong>eclipses de Sol</strong> solo ocurren en luna nueva, y los <strong>de Luna</strong> solo en luna llena. Pero no hay eclipse cada mes.</p></li><li><p>Se repiten siguiendo ciclos regulares; el más conocido, el <strong>saros</strong>, dura unos 18 años y 11 días.</p></li><li><p>Un eclipse total de Sol solo se ve en una franja estrecha de terreno; uno de Luna se ve a la vez desde toda la mitad nocturna del mundo.</p></li><li><p>En un eclipse total de Luna, esta no desaparece: se vuelve rojiza.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>Los tipos de eclipse</h3>\n<p><strong>De Sol:</strong></p>\n<ul><li><p><strong>Total</strong>: el disco solar queda tapado por completo durante unos instantes (la fase de totalidad) y se ve la corona.</p></li><li><p><strong>Parcial</strong>: solo se tapa una parte.</p></li><li><p><strong>Anular</strong>: se tapa el centro pero queda un anillo de Sol visible.</p></li><li><p><strong>Híbrido</strong>: total en unos lugares y anular en otros, a lo largo de la misma franja.</p></li></ul>\n<p><strong>De Luna:</strong></p>\n<ul><li><p><strong>Total</strong>: la Luna entera se oscurece y enrojece.</p></li><li><p><strong>Parcial</strong>: solo una parte entra en la sombra oscura.</p></li><li><p><strong>Penumbral</strong>: la Luna apenas se oscurece levemente, a menudo sin que se note a simple vista.</p></li><li><p><strong>Penumbral total</strong>: la Luna entra por completo en la penumbra, pero sin llegar a tocar la sombra oscura; es poco frecuente y de oscurecimiento sutil.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "tipos-eclipse", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Cómo se ve cada tipo de eclipse desde el suelo. Esquema, no a escala."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'imagen', '{"tipo": "foto", "url": "https://www.nasa.gov/wp-content/uploads/2023/03/36329608000_2e0f627e4b_o.jpg", "enlace": "https://www.nasa.gov/image-article/suns-corona-seen-during-2017-solar-eclipse/", "pie": "Eclipse total de Sol del 21 de agosto de 2017, fotografiado desde un avión sobre Oregón (Estados Unidos): durante la totalidad se ve la corona.", "credito": "NASA/Carla Thomas", "licencia": "Dominio público", "fecha": "2017"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/potw2221a.jpg", "enlace": "https://www.eso.org/public/images/potw2221a/", "pie": "Eclipse total de Luna del 15 de mayo de 2022, visto desde el observatorio Paranal (Chile): durante la totalidad la Luna toma un tono rojizo.", "credito": "F. Aedo, F. Durán/ESO", "licencia": "CC BY 4.0", "grande": "https://cdn.eso.org/images/large/potw2221a.jpg", "fecha": "2022"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que un eclipse de Sol ocurre cuando la Luna se interpone entre el Sol y la Tierra, y uno de Luna cuando la Tierra se interpone y proyecta su sombra sobre ella. No ocurren cada mes porque la órbita lunar está inclinada unos 5° respecto a la eclíptica, y solo se alinean los tres en ciertas épocas. El eclipse anular se da cuando la Luna está en la parte más lejana de su órbita y se ve algo más pequeña que el Sol. El color rojo de la Luna se atribuye a la luz solar que atraviesa la atmósfera terrestre y se curva hacia ella.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>Para los eclipses de Sol, muchos defensores aceptan que es la Luna la que pasa por delante. Para los de Luna no recurren a la sombra de la Tierra, porque en su modelo la Tierra no se interpone entre el Sol y la Luna. Hay dos propuestas principales:</p>\n<ul><li><p><strong>Un cuerpo oscuro y semitransparente.</strong> Rowbotham (1881) rechazó la sombra de la Tierra y propuso que entre la Luna y el observador pasa un cuerpo no luminoso y semitransparente, quizá un satélite oscuro. Como apoyo citaba que durante la totalidad la Luna puede verse rojiza o incluso brillante, algo que, a su juicio, una simple sombra no explicaría.</p></li><li><p><strong>El «objeto de sombra».</strong> La wiki de la Flat Earth Society habla de un objeto no visto que orbita cerca del Sol y que, al pasar entre el Sol y la Luna, proyecta su sombra sobre ella. Le atribuye una inclinación de unos 5° y deja abierto que pudiera ser un cuerpo ya conocido; no precisa su tamaño ni su naturaleza.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 8, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Fueron los grandes registradores de eclipses. Durante siglos los anotaron en los llamados <em>Diarios astronómicos</em> y en la serie <em>Enuma Anu Enlil</em>, y a partir de esas listas descubrieron que se repetían en ciclos, lo que les permitió predecir los eclipses de Luna.</p>\n<p><strong>Egipcios.</strong> Sorprendentemente, se han conservado muy pocos registros egipcios claros de eclipses, pese a su observación del cielo.</p>\n<p><strong>Griegos.</strong> Heródoto cuenta que Tales de Mileto predijo un eclipse de Sol (habitualmente fechado en el 585 a. C.), aunque los historiadores discuten cómo pudo hacerlo. Aristóteles usó los eclipses de Luna como argumento: la sombra de la Tierra sobre la Luna es siempre curva, lo que para él probaba una Tierra esférica. El <strong>mecanismo de Anticitera</strong> (siglos II-I a. C.), hallado en un naufragio, es un artefacto de engranajes que calculaba ciclos de eclipses.</p>\n<p><strong>Romanos y Ptolomeo.</strong> El <em>Almagesto</em> dedica capítulos enteros al cálculo de eclipses, apoyándose en registros babilónicos antiguos.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El libro de Joel (2:31) habla del Sol convertido en tinieblas y la Luna en sangre, una imagen que muchos lectores relacionan con los eclipses. El Talmud (Sucot 29a) trata de los eclipses, pero en clave de significado, que corresponde al módulo 8.</p>\n<p><strong>Libro de Enoc.</strong> En los textos conservados del <em>Libro de las Luminarias</em> no aparece una descripción explícita de los eclipses. Su cielo de puertas y recorridos ordenados se centra en la regularidad de los astros, no en estas excepciones.</p>\n<p><strong>Cristianismo medieval.</strong> Heredó de Ptolomeo el cálculo de eclipses. Un debate famoso giró en torno a la oscuridad que, según los Evangelios, cubrió la tierra en la crucifixión: autores como Orígenes ya observaron que no pudo ser un eclipse solar normal, porque la Pascua judía cae en luna llena, y un eclipse de Sol solo ocurre en luna nueva.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 7, 'los-planetas-los-astros-errantes', 'Los planetas: los astros errantes' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>A simple vista se ven cinco \"estrellas\" que no siguen al resto: <strong>Mercurio, Venus, Marte, Júpiter y Saturno</strong>. La palabra <em>planeta</em> viene del griego y significa \"errante\".</p></li><li><p>Se mueven siempre cerca de la eclíptica, el mismo camino que el Sol y la Luna.</p></li><li><p>De vez en cuando parecen frenar, retroceder y volver a avanzar: es el <strong>movimiento retrógrado</strong>.</p></li><li><p>Mercurio y Venus nunca se alejan mucho del Sol: se ven al amanecer o al anochecer, de ahí el \"lucero del alba\" y el \"lucero vespertino\".</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que los planetas, incluida la Tierra, giran alrededor del Sol. El retroceso aparente se debe a la perspectiva: cuando la Tierra adelanta a un planeta más lento, este parece ir hacia atrás, como un coche que adelantamos en la autopista. Mercurio y Venus siempre están cerca del Sol porque sus órbitas son interiores a la nuestra. Este modelo se fue construyendo con Copérnico (1543), Kepler, que propuso órbitas elípticas (1609), y Galileo, que con el telescopio vio las lunas de Júpiter y las fases de Venus (1610).</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'animacion', '{"componente": "retrogrado", "etiqueta": "Animación", "modelo": "Tres modelos comparados", "pie": "Un mismo bucle de Marte con tres disposiciones: la heliocéntrica de Copérnico y Kepler, la geocéntrica de Ptolomeo con epiciclos y la de la Flat Earth Society, con los planetas girando alrededor de un Sol que da vueltas sobre el centro del plano. Esquemas simplificados."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista suele considerar los planetas como luminarias errantes en el firmamento, no como mundos. Para el movimiento retrógrado, la wiki de la Flat Earth Society propone que los planetas giran alrededor del Sol y que el Sol, a su vez, da vueltas sobre el centro del plano: la suma de los dos giros haría que, vistos desde la Tierra, algunos planetas dibujen bucles hacia atrás. Es una disposición parecida a la que propuso Tycho Brahe en 1588 para un mundo con la Tierra quieta en el centro.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Asociaban cada planeta a una divinidad: Júpiter a Marduk, Venus a Ishtar, Marte a Nergal. Siguieron sus movimientos durante siglos y desarrollaron esquemas aritméticos para predecir sus posiciones, incluidos los retrocesos. La llamada <em>Tablilla de Venus de Ammisaduqa</em> registra las apariciones y desapariciones de Venus.</p>\n<p><strong>Egipcios.</strong> Conocían los cinco planetas visibles y los representaban como dioses navegando por el cielo; varios llevaban nombres relacionados con Horus.</p>\n<p><strong>Griegos.</strong> Eudoxo (siglo IV a. C.) explicó los movimientos planetarios con esferas encajadas que giraban sobre ejes distintos. Aristarco de Samos (siglo III a. C.) propuso ya un modelo con el Sol en el centro, que no fue aceptado en su tiempo.</p>\n<p><strong>Romanos y Ptolomeo.</strong> El <em>Almagesto</em> explica el retroceso con los <strong>epiciclos</strong>: cada planeta gira en un círculo pequeño cuyo centro, a su vez, recorre un círculo grande alrededor de la Tierra. Este modelo predecía las posiciones con notable precisión y se usó durante unos catorce siglos.</p>\n<p><strong>Cosmología bíblica.</strong> La Biblia apenas distingue los planetas de las estrellas. Isaías 14:12 menciona al \"lucero, hijo de la aurora\", que suele identificarse con Venus.</p>\n<p><strong>Libro de Enoc.</strong> En el <em>Libro de los Vigilantes</em> (capítulos 18 y 21), Enoc ve siete estrellas castigadas \"porque no salieron a su tiempo\". Algunos estudiosos han propuesto que se refiere a los planetas, cuyo movimiento irregular no encaja en el orden de las demás estrellas. Es una interpretación, no algo que el texto diga expresamente.</p>\n<p><strong>Cristianismo medieval.</strong> Cada planeta tenía su esfera, y teólogos como Tomás de Aquino discutieron si esas esferas eran movidas por inteligencias o ángeles. En la <em>Divina Comedia</em>, Dante asciende de esfera en esfera, de la Luna a Saturno.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 8, 'el-zodiaco-y-las-constelaciones', 'El zodiaco y las constelaciones' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>Las estrellas forman grupos reconocibles que mantienen su forma a lo largo de toda una vida humana: las <strong>constelaciones</strong>.</p></li><li><p>El Sol, la Luna y los planetas recorren siempre la misma franja de constelaciones: el <strong>zodiaco</strong>.</p></li><li><p>Por la precesión (ver el apartado de Polaris), el punto donde está el Sol en el equinoccio de primavera se desplaza lentamente por el zodiaco. Hace unos dos mil años estaba en Aries; hoy está en Piscis, acercándose a Acuario.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que las estrellas de una constelación suelen estar a distancias muy distintas de nosotros y solo parecen agrupadas desde la Tierra. La Unión Astronómica Internacional reconoce oficialmente <strong>88 constelaciones</strong>, con fronteras fijadas en 1930, y según esas fronteras la eclíptica atraviesa trece, porque también cruza Ofiuco.</p>\n<p>Aquí conviven dos sistemas que conviene no confundir. Las <strong>constelaciones</strong> son grupos de estrellas de tamaños desiguales. Los <strong>signos</strong> de la astrología occidental son doce partes iguales de 30° que empiezan en el equinoccio de primavera: es el llamado <strong>zodiaco tropical</strong>, ligado a las estaciones y no a las estrellas, así que con la precesión los signos y las constelaciones del mismo nombre se han ido separando. La astrología védica usa en cambio un <strong>zodiaco sideral</strong>, que sigue a las estrellas. Cada sistema mide una cosa distinta; el módulo 7 lo verá con detalle.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "zodiaco", "etiqueta": "Interactivo", "modelo": "Constelaciones y signos", "pie": "Fuera, las constelaciones por las que pasa el Sol; dentro, los doce signos del zodiaco tropical, que empiezan en el equinoccio. Mueve el año para ver cómo se separan."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>En el modelo terraplanista las estrellas son luces situadas en la cúpula o firmamento, a no mucha distancia, y las constelaciones son figuras de esa misma bóveda que gira en torno al polo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Muchas de nuestras constelaciones vienen de ellos. Las tablillas MUL.APIN enumeran unas diecisiete constelaciones \"en el camino de la Luna\", y hacia el siglo V a. C. los astrónomos babilónicos fijaron el zodiaco de doce signos iguales.</p>\n<p><strong>Egipcios.</strong> Usaban los <strong>decanos</strong>: 36 grupos de estrellas que salían sucesivamente, cada uno durante unos diez días, y que servían para medir las horas de la noche. El famoso <strong>zodiaco de Dendera</strong> es ya de época ptolemaica (hacia el 50 a. C.) y combina los decanos egipcios con los signos babilónicos y griegos.</p>\n<p><strong>Griegos.</strong> Recibieron el zodiaco de Babilonia y le dieron sus mitos. El poema <em>Fenómenos</em> de Arato describe las constelaciones, y Ptolomeo cataloga 48 en el <em>Almagesto</em>, base de las que usamos hoy.</p>\n<p><strong>Romanos.</strong> Poetas como Manilio, en su <em>Astronómica</em> (siglo I d. C.), divulgaron en latín el zodiaco y las constelaciones.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El libro de Job (9:9 y 38:31-32) nombra las Pléyades, Orión, la Osa y las <em>Mazzaroth</em>, palabra que muchos traducen como las constelaciones o el zodiaco. En sinagogas antiguas de Galilea, como la de Hamat Tiberias (siglo IV) y la de Beit Alfa (siglo VI), se han hallado mosaicos con la rueda del zodiaco.</p>\n<p><strong>Cábala.</strong> El <em>Séfer Yetzirá</em>, uno de sus textos fundacionales, organiza el cosmos en correspondencias: doce letras del alfabeto hebreo para los doce signos, siete para los siete planetas. Aquí solo se señala esa estructura; su significado se verá en el módulo 8.</p>\n<p><strong>Libro de Enoc.</strong> El <em>Libro de las Luminarias</em> describe estrellas con \"jefes\" que las guían en su orden y en sus meses, y doce puertas en los confines del cielo. Todo el cielo aparece como un sistema ordenado de puertas, guardianes y turnos, que Uriel enseña a Enoc.</p>\n<p><strong>Cristianismo medieval.</strong> El zodiaco se integró en el calendario: en catedrales como Chartres o Amiens se esculpieron los signos junto a los trabajos de cada mes.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Description_of_Egypt._2nd_edition._1822._Vol._4._Pl._21_%28Dendera_Circular_Zodiac%29.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Description_of_Egypt._2nd_edition._1822._Vol._4._Pl._21_%28Dendera_Circular_Zodiac%29.jpg", "pie": "El zodiaco circular de Dendera dibujado para la «Description de l''Égypte» (edición de 1822). El original, un relieve de época ptolemaica, se conserva hoy en el Museo del Louvre.", "credito": "Description de l''Égypte", "licencia": "Dominio público", "grande": "https://commons.wikimedia.org/wiki/Special:FilePath/Description_of_Egypt._2nd_edition._1822._Vol._4._Pl._21_%28Dendera_Circular_Zodiac%29.jpg?width=3200", "fecha": "1822"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
