insert into public.modulos (numero, slug, titulo, resumen, publicado) values (9, 'cronologias-en-disputa', 'Cronologías en disputa', 'La cronología estándar académica frente a la «Nueva Cronología» de Anatoli Fomenko, atribuida a él y contrastada. Ninguna se da por sentada.', false);
